#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	// UPROPERTY-rooted: otherwise GC collects the NewObject'd tracker and the
	// raw pointer dangles (shipping crash reading 0xffffffffffffffff, log 2026.10.28).
	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker = nullptr;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "UArenaScoreTracker was created with NewObject in AArenaGameMode::BeginPlay but stored in a raw pointer without UPROPERTY()/TObjectPtr, so it is not rooted. The garbage collector purged it during play (log: 'Collecting garbage: 412 objects purged'), leaving ScoreTracker dangling; the first goal then called UArenaScoreTracker::AddPoints() on freed memory (log: EXCEPTION_ACCESS_VIOLATION reading address 0xffffffffffffffff at Source/PixelArena/ArenaScoreTracker.cpp:18). Fixed by making ScoreTracker a UPROPERTY() TObjectPtr<UArenaScoreTracker> in ArenaGameMode.h.",
  "no_colors_cause": "The palette asset /Game/Data/Palettes/DA_Primary was never cooked into the package: DefaultGame.ini had bCookAll=False and only always-cooked /Game/Data/Effects, while the palette lives in /Game/Data/Palettes (referenced only by the editor-only LoadObject soft path). Log: \"Couldn't find file for package /Game/Data/Palettes/DA_Primary\" then 'Palette is null, using fallback gray'. Fixed by adding +DirectoriesToAlwaysCook=(Path=\"/Game/Data/Palettes\") to Config/DefaultGame.ini."
}
